window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ad0275825d53ca5"]={"versions": [{"id": "FIG-3ad0275825d53ca5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodik-Notation zur Modellierung einer spezifischen Entwicklungsaktivität innerhalb der Basic-Software-Entwicklung (BSW). Das Diagramm veranschaulicht die Einbettung der Aktivität „Define BSW Types“ in den Methoden- und Rollenkontext der AUTOSAR-Entwicklungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>Basic Software Designer</code> (mit Stereotyp <code>«performs»</code>, Multiplizität 1 am Aktivitätsknoten)</li>\n<li><code>Basic Software Module Developer</code> (mit Stereotyp <code>«performs»</code>)</li>\n<li><strong>Aktivität:</strong></li>\n<li><code>Define BSW Types</code> (zentraler Prozessschritt)</li>\n<li><strong>Artefakte / Work Products:</strong></li>\n<li><code>BSW Standard Package</code> (Briefumschlag-Symbol mit Bindung links, Rolle <code>«input»</code>, Multiplizität <code>0..1</code> am Ausgang des Artefakts)</li>\n<li><code>BSW Types</code> (Dokumenten-Symbol, Rolle <code>«inoutput»</code>, Multiplizität <code>0..1</code> an der Aktivitätsspitze)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Define BSW Types</code> wird von den Rollen <code>Basic Software Designer</code> und/oder <code>Basic Software Module Developer</code> ausgeführt (gekennzeichnet über eingehende <code>«performs»</code>-Assoziationen).</li>\n<li>Als optionaler Eingang dient das Artefakt <code>BSW Standard Package</code> (Kardinalität <code>0..1</code>), das über einen gerichteten Kontroll-/Datenfluss (<code>«input»</code>) in die Aktivität eingeht.</li>\n<li>Die Aktivität modifiziert bzw. erzeugt und aktualisiert das Artefakt <code>BSW Types</code> in einer bidirektionalen Beziehung (gekennzeichnet über <code>«inoutput»</code> mit Kardinalität <code>0..1</code> an der Aktivitätskante).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert die für BSW-Module erforderlichen Datentypen. Die Kardinalität <code>0..1</code> bei <code>BSW Standard Package</code> kennzeichnet die optionale Verfügbarkeit eines standardisierten Pakets als Basis. Die <code>«inoutput»</code>-Beziehung zu <code>BSW Types</code> mit Kardinalität <code>0..1</code> weist darauf hin, dass bestehende Typbeschreibungen eingelesen, erweitert oder neu angelegt werden. Werkzeuge müssen die Erstellung sowie inkrementelle Aktualisierung der BSW-Typdefinitionen unter Einhaltung der entsprechenden AUTOSAR-Schemata unterstützen.</p>"}, {"id": "FIG-b39cee5608ddb071", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodik-Notation zur Modellierung einer spezifischen Entwicklungsaktivität innerhalb der Basic-Software-Entwicklung (BSW). Das Diagramm veranschaulicht die Einbettung der Aktivität „Define BSW Types“ in den Methoden- und Rollenkontext der AUTOSAR-Entwicklungsumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen / Akteure:</strong></li>\n<li><code>Basic Software Designer</code> (mit Stereotyp <code>«performs»</code>, Multiplizität 1 am Aktivitätsknoten)</li>\n<li><code>Basic Software Module Developer</code> (mit Stereotyp <code>«performs»</code>)</li>\n<li><strong>Aktivität:</strong></li>\n<li><code>Define BSW Types</code> (zentraler Prozessschritt)</li>\n<li><strong>Artefakte / Work Products:</strong></li>\n<li><code>BSW Standard Package</code> (Briefumschlag-Symbol mit Bindung links, Rolle <code>«input»</code>, Multiplizität <code>0..1</code> am Ausgang des Artefakts)</li>\n<li><code>BSW Types</code> (Dokumenten-Symbol, Rolle <code>«inoutput»</code>, Multiplizität <code>0..1</code> an der Aktivitätsspitze)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Define BSW Types</code> wird von den Rollen <code>Basic Software Designer</code> und/oder <code>Basic Software Module Developer</code> ausgeführt (gekennzeichnet über eingehende <code>«performs»</code>-Assoziationen).</li>\n<li>Als optionaler Eingang dient das Artefakt <code>BSW Standard Package</code> (Kardinalität <code>0..1</code>), das über einen gerichteten Kontroll-/Datenfluss (<code>«input»</code>) in die Aktivität eingeht.</li>\n<li>Die Aktivität modifiziert bzw. erzeugt und aktualisiert das Artefakt <code>BSW Types</code> in einer bidirektionalen Beziehung (gekennzeichnet über <code>«inoutput»</code> mit Kardinalität <code>0..1</code> an der Aktivitätskante).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert die für BSW-Module erforderlichen Datentypen. Die Kardinalität <code>0..1</code> bei <code>BSW Standard Package</code> kennzeichnet die optionale Verfügbarkeit eines standardisierten Pakets als Basis. Die <code>«inoutput»</code>-Beziehung zu <code>BSW Types</code> mit Kardinalität <code>0..1</code> weist darauf hin, dass bestehende Typbeschreibungen eingelesen, erweitert oder neu angelegt werden. Werkzeuge müssen die Erstellung sowie inkrementelle Aktualisierung der BSW-Typdefinitionen unter Einhaltung der entsprechenden AUTOSAR-Schemata unterstützen.</p>"}], "trans": [{"from": "FIG-3ad0275825d53ca5", "to": "FIG-b39cee5608ddb071", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
